public class Main {
  public static void main(String[] args) {
    java.util.Scanner in=new java.util.Scanner(System.in);
    int n=in.nextInt(),p=in.nextInt(),s=0;for(int i=1;i<n;i++){int v=in.nextInt();s+=Math.abs(v-p);p=v;}System.out.println(s+8);
  }
}

